(()=>{
 const api=PeninsulaColors,host=document.querySelector('#color-settings');if(!host)return;let selected='heading';
 host.innerHTML='<h2>Настройки цвета</h2><div class="color-tabs" role="tablist" aria-label="Блоки игры">'+Object.entries(api.names).map(([id,label])=>'<button type="button" role="tab" id="color-tab-'+id+'" aria-controls="color-controls" data-color-preset="'+id+'">'+label+'</button>').join('')+'</div><div id="color-controls" role="tabpanel"><label>Цвет фона<input data-color-field="background" type="color"></label><label>Прозрачность текстуры камня<div class="texture-control"><input data-texture-range type="range" min="0" max="100" step="1"><input aria-label="Прозрачность текстуры камня, %" data-texture-number type="number" min="0" max="100" step="1"><span>%</span></div></label><label>Цвет контура<input data-color-field="border" type="color"></label></div>';
 function sync(){host.querySelectorAll('[data-color-preset]').forEach(e=>{const active=e.dataset.colorPreset===selected;e.setAttribute('aria-selected',String(active));e.tabIndex=active?0:-1});host.querySelector('[role="tabpanel"]').setAttribute('aria-labelledby','color-tab-'+selected);host.querySelectorAll('[data-color-field]').forEach(e=>e.value=api.get(selected)[e.dataset.colorField]);for(const e of host.querySelectorAll('[data-texture-range],[data-texture-number]'))e.value=100-api.get(selected).textureOpacity}
 host.addEventListener('click',e=>{const tab=e.target.closest('[data-color-preset]');if(tab){selected=tab.dataset.colorPreset;sync()}});
 host.querySelector('[role="tablist"]').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const ids=Object.keys(api.names);selected=ids[e.key==='Home'?0:e.key==='End'?ids.length-1:(ids.indexOf(selected)+(e.key==='ArrowLeft'?ids.length-1:1))%ids.length];sync();host.querySelector('[data-color-preset="'+selected+'"]').focus()});
 host.addEventListener('input',e=>{const field=e.target.dataset.colorField,isTexture=e.target.matches('[data-texture-range],[data-texture-number]');if(!field&&!isTexture||isTexture&&e.target.value==='')return;const value=JSON.parse(JSON.stringify(api.state));if(field)value[selected][field]=e.target.value;if(isTexture)value[selected].textureOpacity=100-Number(e.target.value);api.update(value);sync()});
 window.addEventListener('color-presets-change',()=>{sync();if(typeof levelFrame!=='undefined'&&!levelFrame.hidden)levelFrame.contentWindow.postMessage({type:'color-presets',settings:api.state},location.origin);if(typeof render==='function'&&currentUI.fonts.cozette?.image)render()});sync();
})();
